@pytest.mark.skip(reason="a check sends this turn to the model a second time, and the scripted model then repeats every call: the scripted run says nothing here; the live test below is the guard")
async def test_replay_two_steels_told_apart_285() -> None:
    turn, _api = await replay(RECORDED)
    # WA-277 step A: the trace of that day does not keep everything the code reads around the model (the site
    # they were on, the catalogue and unit reads), so this pins what TODAY's code does with the same calls;
    # what production held then is in RECORDED["pending"]. The live test below is the guard of the behaviour.
    assert [c["tool"] for c in turn.calls] == ['search_materials', 'day_summary', 'record_receipt', 'record_receipt', 'ask', 'search_materials', 'day_summary', 'record_receipt', 'record_receipt', 'ask']
    assert [e.summary for e in turn.pending] == ['20 ton Tata Steel, Green villa kerala', '30 ton TMT Steel, Green villa kerala']


